  'Required student fields: first_name, gender, date_of_birth, admission_date, nationality, present_address and permanent_address. Academic session, class and section IDs are also required.': 'শিক্ষার্থীর আবশ্যক তথ্য: নাম, লিঙ্গ, জন্মতারিখ, ভর্তির তারিখ, জাতীয়তা, বর্তমান ও স্থায়ী ঠিকানা। শিক্ষাবর্ষ, শ্রেণি ও শাখার পরিচিতি নম্বরও দিতে হবে।',
  'Leave admission_no blank to generate a unique admission number. Email, roll number and last name are optional. Duplicate admission numbers, student/account emails, or rolls in the same session, class and section are rejected.': 'ভর্তি নম্বর খালি রাখলে স্বতন্ত্র নম্বর তৈরি হবে। ইমেইল, রোল ও শেষ নাম ঐচ্ছিক। একই শিক্ষাবর্ষ, শ্রেণি ও শাখায় পুনরাবৃত্ত ভর্তি নম্বর, ইমেইল বা রোল গ্রহণ করা হবে না।',
  'This import creates student records and enrollments. It does not create portal accounts, set passwords or send messages.': 'এতে শিক্ষার্থীর তথ্য ও ভর্তি নিবন্ধন তৈরি হবে। পোর্টাল অ্যাকাউন্ট বা পাসওয়ার্ড তৈরি হবে না এবং কোনো বার্তা পাঠানো হবে না।',
