    'Manage vehicles, drivers, routes, fuel logs, and student boarding.': 'যানবাহন, চালক, যাত্রাপথ, জ্বালানির হিসাব এবং শিক্ষার্থীদের ওঠানামা পরিচালনা করুন।',
