    'Use lowercase letters, numbers and hyphens only.': 'শুধু ছোট হাতের ইংরেজি বর্ণ, সংখ্যা ও হাইফেন ব্যবহার করুন।',
    'Attendance, finance, communication and daily operations—সব গুরুত্বপূর্ণ তথ্য এক জায়গায়।': 'উপস্থিতি, অর্থব্যবস্থা, যোগাযোগ ও দৈনন্দিন কাজের সব গুরুত্বপূর্ণ তথ্য এক জায়গায়।',
    'কোনো student profile linked নেই': 'কোনো শিক্ষার্থীর প্রোফাইল যুক্ত নেই।',
    'School office থেকে এই parent account-এর সঙ্গে student link করুন।': 'বিদ্যালয়ের কার্যালয় থেকে এই অভিভাবক অ্যাকাউন্টের সঙ্গে শিক্ষার্থী যুক্ত করুন।',
    'Subject-wise marks, grade, GPA ও result status দেখুন।': 'বিষয়ভিত্তিক নম্বর, গ্রেড, জিপিএ ও ফলাফলের অবস্থা দেখুন।',
    'Result দেখার permission এখনো দেওয়া হয়নি। School admin permission দিলে এখানে button দেখা যাবে।': 'ফলাফল দেখার অনুমতি এখনো দেওয়া হয়নি। বিদ্যালয়ের প্রশাসক অনুমতি দিলে এখানে বোতাম দেখা যাবে।',
